// Asset catalog: loads data.json (generated by tools/catalog/build.mjs) and renders a
// searchable, filterable, sortable grid with a detail drawer for each asset.
(() => {
  const $ = (id) => document.getElementById(id);
  const REPO = 'https://github.com/ariFialkov/vampire-samurai/blob/claude/sweet-fermi-vypltj/';
  const CATS = [['all', 'All'], ['Samurai', 'Samurai'], ['Monster', 'Monsters'], ['Weapon', 'Weapons'], ['Collectible', 'Collectibles']];
  const CAT_ORDER = { Samurai: 0, Monster: 1, Weapon: 2, Collectible: 3 };
  const VIEW_ORDER = ['three-quarter', 'front', 'side', 'back', 'action'];
  const state = { q: '', cat: 'all', sort: 'category', desc: false, list: [], current: -1, view: null };
  let assets = [];

  const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const highlight = (text) => {
    const t = esc(text);
    if (!state.q) return t;
    const words = state.q.split(/\s+/).filter(Boolean).map((w) => w.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'));
    return words.length ? t.replace(new RegExp(`(${words.join('|')})`, 'gi'), '<mark>$1</mark>') : t;
  };
  const toast = (msg) => { const t = $('toast'); t.textContent = msg; t.classList.add('show'); clearTimeout(toast.t); toast.t = setTimeout(() => t.classList.remove('show'), 1600); };
  const fmtM = (n) => `${Number(n).toFixed(2)} m`;
  const fmtN = (n) => Number(n).toLocaleString('en-US');

  function haystack(a) {
    return [a.name, a.category, a.subcategory, a.description, a.look, ...(a.tags ?? []), ...(a.animations ?? []),
      ...Object.entries(a.stats ?? {}).flat(), ...(a.palette ?? [])].join(' ').toLowerCase();
  }

  const SORTS = {
    category: (a, b) => CAT_ORDER[a.category] - CAT_ORDER[b.category] || (a.tier ?? 0) - (b.tier ?? 0) || a.name.localeCompare(b.name),
    name: (a, b) => a.name.localeCompare(b.name),
    height: (a, b) => a.size.height - b.size.height,
    footprint: (a, b) => a.size.width * a.size.depth - b.size.width * b.size.depth,
    triangles: (a, b) => a.triangles - b.triangles,
    tier: (a, b) => (a.tier ?? 99) - (b.tier ?? 99) || a.name.localeCompare(b.name),
  };

  function filtered() {
    const words = state.q.toLowerCase().split(/\s+/).filter(Boolean);
    let list = assets.filter((a) => (state.cat === 'all' || a.category === state.cat) && words.every((w) => a._hay.includes(w)));
    list = list.slice().sort(SORTS[state.sort]);
    if (state.desc) list.reverse();
    return list;
  }

  function renderChips() {
    const words = state.q.toLowerCase().split(/\s+/).filter(Boolean);
    const matches = (a) => words.every((w) => a._hay.includes(w));
    $('chips').innerHTML = CATS.map(([key, label]) => {
      const n = assets.filter((a) => (key === 'all' || a.category === key) && matches(a)).length;
      return `<button class="chip" role="tab" data-cat="${key}" aria-selected="${state.cat === key}">${label}<span>${n}</span></button>`;
    }).join('');
  }

  function card(a, i) {
    const main = a.images['three-quarter'] ?? Object.values(a.images)[0];
    const alt = a.images.action ?? a.images.front;
    const facts = [`${fmtM(a.size.height)} tall`, `${fmtN(a.triangles)} tris`];
    if (a.category === 'Weapon') facts[0] = `${fmtM(a.length ?? a.size.height)} long`;
    return `<button class="card" data-i="${i}" aria-label="${esc(a.name)}, ${esc(a.category)}">
      <div class="thumb${alt ? ' has-alt' : ''}">
        <img class="main" src="${main}" alt="" loading="lazy" />${alt ? `<img class="alt" src="${alt}" alt="" loading="lazy" />` : ''}
        <span class="badge">${esc(a.category)}</span>${a.tier ? `<span class="tier" title="Difficulty tier">${a.tier}</span>` : ''}
      </div>
      <div class="body"><h3>${highlight(a.name)}</h3><p class="sub">${highlight(a.subcategory)}</p>
        <div class="facts">${facts.map((f) => `<span>${f}</span>`).join('')}</div></div>
    </button>`;
  }

  function render() {
    state.list = filtered();
    renderChips();
    const grid = $('grid');
    const groups = state.sort === 'category' && state.cat === 'all' && !state.q;
    let html = '', last = null;
    state.list.forEach((a, i) => {
      if (groups && a.category !== last) { last = a.category; html += `<h2 class="section-label">${esc(CATS.find((c) => c[0] === a.category)[1])}</h2>`; }
      html += card(a, i);
    });
    grid.innerHTML = html;
    $('count').textContent = `${state.list.length} of ${assets.length} assets`;
    const empty = $('empty');
    empty.classList.toggle('hidden', state.list.length > 0);
    empty.textContent = state.list.length ? '' : `No assets match "${state.q}". Try a name, a weapon style or a colour like #c0392b.`;
  }

  // ---------------------------------------------------------------- detail drawer
  function section(title, body) { return body ? `<section><h4>${esc(title)}</h4>${body}</section>` : ''; }
  function openAsset(i, push = true) {
    if (i < 0 || i >= state.list.length) return;
    state.current = i;
    const a = state.list[i];
    const views = VIEW_ORDER.filter((v) => a.images[v]);
    state.view = views[0];
    $('d-cat').textContent = `${a.category} · ${a.subcategory}`;
    $('d-name').textContent = a.name;
    $('d-tabs').innerHTML = views.length > 1 ? views.map((v) => `<button role="tab" data-view="${v}" aria-selected="${v === state.view}">${v.replace('-', ' ')}</button>`).join('') : '';
    setView(state.view);
    const kv = [['Height', fmtM(a.size.height)], ['Width', fmtM(a.size.width)], ['Depth', fmtM(a.size.depth)], ['Triangles', fmtN(a.triangles)], ['Meshes', a.meshes], ['Materials', a.materials]];
    if (a.scale && a.scale !== 1) kv.push(['Scale', `${a.scale}x`]);
    if (a.tier) kv.push(['Difficulty', `${a.tier} of 7`]);
    const props = a.proportions ? Object.entries(a.proportions).map(([k, v]) => [k.replace(/([A-Z])/g, ' $1'), v]) : [];
    $('d-info').innerHTML =
      section('Overview', `<p>${esc(a.description)}</p>${a.look ? `<p class="dim">${esc(a.look)}</p>` : ''}`) +
      section('Dimensions and geometry', `<dl class="kv">${kv.map(([k, v]) => `<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl>`) +
      section('Proportions', props.length ? `<dl class="kv">${props.map(([k, v]) => `<div><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl>` : '') +
      section('Palette', a.palette?.length ? `<div class="swatches">${a.palette.map((c) => `<button class="swatch" data-copy="${c}" title="Copy ${c}"><i style="background:${c}"></i>${c}</button>`).join('')}</div>` : '') +
      section('Gameplay', a.stats ? `<table><tbody>${Object.entries(a.stats).map(([k, v]) => `<tr><th>${esc(k)}</th><td>${esc(v)}</td></tr>`).join('')}</tbody></table>` : '') +
      section('Animations to support', a.animations?.length ? `<ul class="list">${a.animations.map((x) => `<li>${esc(x)}</li>`).join('')}</ul>` : '') +
      section('Rig pivots (metres, model space)', a.rig ? `<p class="dim">${esc(a.rig.type)}</p><table><thead><tr><th>Bone</th><th class="num">x</th><th class="num">y</th><th class="num">z</th></tr></thead><tbody>${a.rig.bones.map((b) => `<tr><td>${esc(b.bone)}</td>${b.position.map((n) => `<td class="num">${n.toFixed(2)}</td>`).join('')}</tr>`).join('')}</tbody></table><div class="row-actions"><button class="btn small ghost" data-copy-rig>Copy rig as JSON</button></div>` : '') +
      section('Attach points', a.attach?.length ? `<table><tbody>${a.attach.map((x) => `<tr><th>${esc(x.point)}</th><td>${esc(x.holds)}</td></tr>`).join('')}</tbody></table>` : '') +
      section('Source', `<ul class="list src">${(a.source ?? []).map((f) => `<li><a href="${REPO}${f}" target="_blank" rel="noopener">${esc(f)}</a></li>`).join('')}</ul>`) +
      section('Tags', `<div class="tags">${(a.tags ?? []).map((t) => `<span>${esc(t)}</span>`).join('')}</div>`);
    $('d-prev').disabled = i === 0; $('d-next').disabled = i === state.list.length - 1;
    const d = $('drawer'); d.setAttribute('aria-hidden', 'false');
    document.body.style.overflow = 'hidden';
    if (push) history.replaceState(null, '', `#${a.id}`);
    d.querySelector('.d-body').scrollTop = 0;
  }
  function setView(v) {
    const a = state.list[state.current];
    state.view = v;
    $('d-img').src = a.images[v]; $('d-img').alt = `${a.name}, ${v.replace('-', ' ')} view`;
    const dl = $('d-download'); dl.href = a.images[v]; dl.setAttribute('download', a.images[v].split('/').pop());
    for (const b of $('d-tabs').querySelectorAll('button')) b.setAttribute('aria-selected', String(b.dataset.view === v));
  }
  function closeDrawer() {
    $('drawer').setAttribute('aria-hidden', 'true');
    document.body.style.overflow = '';
    history.replaceState(null, '', location.pathname + location.search);
    const c = document.querySelector(`.card[data-i="${state.current}"]`); c?.focus();
    state.current = -1;
  }

  // ---------------------------------------------------------------- events
  function bind() {
    $('q').addEventListener('input', (e) => { state.q = e.target.value.trim(); render(); });
    $('chips').addEventListener('click', (e) => { const b = e.target.closest('[data-cat]'); if (!b) return; state.cat = b.dataset.cat; render(); });
    $('sort').addEventListener('change', (e) => { state.sort = e.target.value; state.desc = ['height', 'footprint', 'triangles'].includes(state.sort); $('dir').dataset.desc = state.desc; render(); });
    $('dir').addEventListener('click', () => { state.desc = !state.desc; $('dir').dataset.desc = state.desc; render(); });
    $('grid').addEventListener('click', (e) => { const c = e.target.closest('.card'); if (c) openAsset(Number(c.dataset.i)); });
    $('drawer').addEventListener('click', (e) => {
      if (e.target.closest('[data-close]')) return closeDrawer();
      const tab = e.target.closest('[data-view]'); if (tab) return setView(tab.dataset.view);
      const sw = e.target.closest('[data-copy]'); if (sw) { navigator.clipboard?.writeText(sw.dataset.copy).then(() => toast(`Copied ${sw.dataset.copy}`), () => toast(sw.dataset.copy)); return; }
      if (e.target.closest('[data-copy-rig]')) { const a = state.list[state.current]; navigator.clipboard?.writeText(JSON.stringify(a.rig, null, 2)).then(() => toast('Rig copied as JSON')); }
    });
    $('d-prev').addEventListener('click', () => openAsset(state.current - 1));
    $('d-next').addEventListener('click', () => openAsset(state.current + 1));
    document.addEventListener('keydown', (e) => {
      const open = state.current >= 0;
      if (e.key === '/' && document.activeElement !== $('q')) { e.preventDefault(); $('q').focus(); return; }
      if (!open) return;
      if (e.key === 'Escape') closeDrawer();
      if (e.key === 'ArrowLeft') openAsset(state.current - 1);
      if (e.key === 'ArrowRight') openAsset(state.current + 1);
    });
  }

  fetch('data.json').then((r) => r.json()).then((data) => {
    assets = data.assets.map((a) => ({ ...a, _hay: haystack(a) }));
    $('meta-line').textContent = `${assets.length} assets · v${data.version} · generated ${data.generated}`;
    $('conventions').innerHTML = data.conventions.map((c) => `<li>${esc(c)}</li>`).join('');
    bind();
    render();
    const fromHash = () => {
      const id = decodeURIComponent(location.hash.slice(1));
      if (!id) return;
      let i = state.list.findIndex((a) => a.id === id);
      if (i < 0) { state.q = ''; state.cat = 'all'; $('q').value = ''; render(); i = state.list.findIndex((a) => a.id === id); }
      if (i >= 0) openAsset(i, false);
    };
    window.addEventListener('hashchange', fromHash);
    fromHash();
  }).catch(() => { $('empty').classList.remove('hidden'); $('empty').textContent = 'Could not load the catalog data.'; });
})();
